import numpy as np

def equalize_histogram(image):
    image = np.asarray(image, dtype=np.uint8)
    counts = np.bincount(image.ravel(), minlength=256)[:256]
    cdf = counts.cumsum()
    nonzero = cdf > 0
    if not nonzero.any():
        return image.copy()
    cdf_min = int(cdf[nonzero].min())
    denom = int(cdf[-1] - cdf_min)
    if denom == 0:
        return image.copy()
    lut = np.round(255.0 * (cdf - cdf_min) / denom)
    lut = np.clip(lut, 0, 255).astype(np.uint8)
    return lut[image]
